SELECT CASE WHEN s.device IN ('desktop', 'mobile') THEN 'priority' ELSE 'other' END AS device_group, SORT_ARRAY(COLLECT_SET(we.page)) AS page_list, ROUND(AVG(we.duration_sec), 2) AS avg_duration_sec FROM web_events we LEFT JOIN sessions s ON we.session_id = s.id WHERE we.session_id IN (13, 28, 29) GROUP BY CASE WHEN s.device IN ('desktop', 'mobile') THEN 'priority' ELSE 'other' END
